-- Cursos da categoria Pós-Graduação.
-- A lista original não tinha descrição: os textos de "resumo" foram escritos
-- a partir do nome de cada curso. A coluna "descricao" é o texto de
-- Modalidade no "Sobre o curso". Pode rodar de novo: slug repetido é ignorado.

insert into public.courses (nivel_id, slug, nome, area, modalidade, carga_horaria, resumo)
select n.id, c.slug, c.nome, c.area, 'EAD', c.carga_horaria, c.resumo
from public.course_niveis n
cross join (values
  ('administracao-publica', 'Administração Pública', 'Negócios', '570 horas', 'Prepara para atuar na gestão de órgãos e entidades públicas, com foco em planejamento governamental, orçamento público, licitações e políticas públicas voltadas a resultados.'),
